using System.ComponentModel.DataAnnotations;

namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeSubmission
{
    [Required(ErrorMessage = "Title is required.")]
    [StringLength(100, MinimumLength = 3, ErrorMessage = "Title must be 3–100 characters.")]
    public string Title { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a category.")]
    public string Category { get; set; } = string.Empty;

    [Required(ErrorMessage = "Ingredients are required.")]
    public string Ingredients { get; set; } = string.Empty;

    [Required(ErrorMessage = "Steps are required.")]
    public string Steps { get; set; } = string.Empty;
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough, Tomato sauce, Fresh mozzarella, Basil, Olive oil", Steps = "1. Preheat oven to 475°F.\n2. Roll out dough.\n3. Spread sauce and add cheese.\n4. Bake 10-12 minutes.\n5. Top with fresh basil.", AverageRating = 4.5, RatingCount = 12 },
        new Recipe { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti, Pancetta, Eggs, Parmesan, Black pepper", Steps = "1. Cook pasta al dente.\n2. Fry pancetta until crispy.\n3. Mix eggs and cheese.\n4. Toss hot pasta with pancetta.\n5. Stir in egg mixture off heat.", AverageRating = 4.8, RatingCount = 20 },
        new Recipe { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken thighs, Yogurt, Tikka spice mix, Tomato sauce, Cream, Rice", Steps = "1. Marinate chicken in spiced yogurt.\n2. Grill or pan-fry chicken.\n3. Simmer tomato sauce with spices.\n4. Add cream and chicken.\n5. Serve over basmati rice.", AverageRating = 4.7, RatingCount = 15 },
        new Recipe { Id = 4, Title = "Vegetable Pad Thai", Category = "Thai", Ingredients = "Rice noodles, Tofu, Bean sprouts, Peanuts, Tamarind sauce, Lime", Steps = "1. Soak noodles in warm water.\n2. Stir-fry tofu until golden.\n3. Add vegetables and noodles.\n4. Toss with tamarind sauce.\n5. Garnish with peanuts and lime.", AverageRating = 4.3, RatingCount = 8 },
        new Recipe { Id = 5, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef, Taco shells, Lettuce, Tomato, Cheese, Sour cream", Steps = "1. Brown beef with taco seasoning.\n2. Warm taco shells.\n3. Assemble with toppings.\n4. Serve with salsa.", AverageRating = 4.2, RatingCount = 10 },
        new Recipe { Id = 6, Title = "Green Curry", Category = "Thai", Ingredients = "Green curry paste, Coconut milk, Chicken, Bamboo shoots, Thai basil", Steps = "1. Fry curry paste in oil.\n2. Add coconut milk.\n3. Add chicken and vegetables.\n4. Simmer 15 minutes.\n5. Finish with Thai basil.", AverageRating = 4.6, RatingCount = 11 },
        new Recipe { Id = 7, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados, Lime juice, Cilantro, Onion, Jalapeño, Salt", Steps = "1. Mash avocados.\n2. Mix in lime juice and salt.\n3. Fold in diced onion, cilantro, jalapeño.\n4. Serve with tortilla chips.", AverageRating = 4.9, RatingCount = 25 },
        new Recipe { Id = 8, Title = "Dal Makhani", Category = "Indian", Ingredients = "Black lentils, Kidney beans, Butter, Cream, Tomatoes, Garam masala", Steps = "1. Soak lentils overnight.\n2. Pressure cook until soft.\n3. Prepare tomato-butter gravy.\n4. Combine and simmer 30 minutes.\n5. Finish with cream.", AverageRating = 4.4, RatingCount = 9 },
    };

    private int _nextId = 9;

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public IReadOnlyList<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetRecipeById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRecipe(RecipeSubmission submission)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients,
            Steps = submission.Steps,
            AverageRating = 0,
            RatingCount = 0
        });
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
        recipe.RatingCount++;
        recipe.AverageRating = totalStars / recipe.RatingCount;
    }
}

@rendermode InteractiveServer
@using RecipeCommunity.Services

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _hoveredStar ? "hovered" : "") @(star <= _selectedStar ? "selected" : "")"
              @onmouseover="() => _hoveredStar = star"
              @onmouseout="() => _hoveredStar = 0"
              @onclick="() => SubmitRating(star)">
            ★
        </span>
    }
    <span class="rating-info">(@AverageRating.ToString("0.0") avg, @RatingCount ratings)</span>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double AverageRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private int _hoveredStar;
    private int _selectedStar;
    private bool _hasRated;

    private void SubmitRating(int stars)
    {
        if (_hasRated) return;

        _selectedStar = stars;
        _hasRated = true;
        RecipeService.AddRating(RecipeId, stars);

        var recipe = RecipeService.GetRecipeById(RecipeId);
        if (recipe is not null)
        {
            AverageRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
    }
}

.star-rating {
    display: inline-flex;
    align-items: center;
    gap: 0.1rem;
}

.star {
    font-size: 1.5rem;
    cursor: pointer;
    color: #ccc;
    transition: color 0.15s;
}

.star.hovered,
.star.selected {
    color: #f5a623;
}

.rating-info {
    margin-left: 0.5rem;
    font-size: 0.9rem;
    color: #666;
}

