arguments.new_str:
@page "/"
@using RecipeCommunity.Services

<PageTitle>Recipe Community</PageTitle>

<div class="hero">
    <h1>🍽️ Recipe Community</h1>
    <p>Discover and share delicious recipes from around the world.</p>
</div>

<h2>Browse by Category</h2>

<div class="category-grid">
    @foreach (var category in RecipeService.GetCategories())
    {
        <a class="category-card" href="/category/@category">
            <h3>@category</h3>
            <p>@RecipeService.GetRecipesByCategory(category).Count recipes</p>
        </a>
    }
</div>

<div class="cta">
    <p>Have a recipe to share?</p>
    <a href="/submit">Submit Your Recipe →</a>
</div>

@code {
    [Inject] private RecipeService RecipeService { get; set; } = default!;
}

arguments.file_text:
@page "/category/{CategoryName}"
@using RecipeCommunity.Services
@using RecipeCommunity.Models

<PageTitle>@CategoryName Recipes</PageTitle>

<h1>@CategoryName Recipes</h1>

<nav><a href="/">← Back to Categories</a></nav>

@if (Recipes.Count == 0)
{
    <p>No recipes found in this category.</p>
}
else
{
    <div class="recipe-list">
        @foreach (var recipe in Recipes)
        {
            <div class="recipe-card">
                <a href="/recipe/@recipe.Id">
                    <h3>@recipe.Title</h3>
                </a>
